        SynonymSetCreateSchema updatedData = new SynonymSetCreateSchema();
        List<SynonymItemSchema> items = new ArrayList<>();
        SynonymItemSchema item = new SynonymItemSchema();
        item.setId("dummy");
        item.setSynonyms(Arrays.asList("foo", "bar", "baz", "qux"));
