        List<StemmingDictionaryWords> stemmingDictionaryWords = new ArrayList<>();

        stemmingDictionaryWords.add(new StemmingDictionaryWords().word("ran").root("run"));
        stemmingDictionaryWords.add(new StemmingDictionaryWords().word("running").root("run"));

        client.stemming().dictionaries().upsert("irregular-plurals", stemmingDictionaryWords);
    }

    public SynonymSetCreateSchema createTestSynonymSetData() {
        SynonymItemSchema synonymItem = new SynonymItemSchema();
        synonymItem.setId("dummy");
        synonymItem.setSynonyms(Arrays.asList("foo", "bar", "baz"));

        SynonymSetCreateSchema synonymSetData = new SynonymSetCreateSchema();
        synonymSetData.setItems(Arrays.asList(synonymItem));
        return synonymSetData;
    }

    public CurationSetCreateSchema createTestCurationSetData() {
        CurationRule rule = new CurationRule();
        rule.setQuery("apple");
        rule.setMatch(CurationRule.MatchEnum.EXACT);

        CurationInclude include1 = new CurationInclude();
        include1.setId("422");
        include1.setPosition(1);
        CurationInclude include2 = new CurationInclude();
        include2.setId("54");
        include2.setPosition(2);

        CurationExclude exclude1 = new CurationExclude();
        exclude1.setId("287");

        CurationItemCreateSchema curationItem = new CurationItemCreateSchema();
        curationItem.setId("dummy");
        curationItem.setRule(rule);
        curationItem.setIncludes(Arrays.asList(include1, include2));
        curationItem.setExcludes(Arrays.asList(exclude1));
        curationItem.setRemoveMatchedTokens(true);
        curationItem.setFilterBy("category:=Electronics");
        curationItem.setStopProcessing(true);

        CurationSetCreateSchema curationSetData = new CurationSetCreateSchema();
        curationSetData.setItems(Arrays.asList(curationItem));
        curationSetData.setDescription("Test curation set");
        return curationSetData;
    }

    public void teardown() throws Exception {
        CollectionResponse[] collectionResponses = client.collections().retrieve();
        for (CollectionResponse c : collectionResponses) {
            if (c.getName() != null) {
                client.collections(c.getName()).delete();
            }
        }

        CollectionAliasesResponse collectionAliasesResponse = client.aliases().retrieve();
        for (CollectionAlias a : collectionAliasesResponse.getAliases()) {
            if (a.getName() != null) {
                client.aliases(a.getName()).delete();
            }
        }

        AnalyticsRules analyticsRules = client.analytics().rules();
        List<AnalyticsRule> rules = analyticsRules.retrieve();
        if (rules != null) {
            for (AnalyticsRule r : rules) {
                if (r.getName() != null) {
                    client.analytics().rules(r.getName()).delete();
                }
            }
        }

        ApiKeysResponse apiKeysResponse = client.keys().retrieve();
        for (ApiKey k : apiKeysResponse.getKeys()) {
            client.keys(k.getId()).delete();
        }

        StopwordsSetsRetrieveAllSchema stopwords = client.stopwords().retrieve();
        for (StopwordsSetSchema s : stopwords.getStopwords()) {
            client.stopwords(s.getId()).delete();
        }

        try {
            SynonymSetSchema[] synonymSets = client.synonymSets().retrieve();
            for (SynonymSetSchema s : synonymSets) {
                if (s.getName() != null) {
                    client.synonymSet(s.getName()).delete();
                }
            }
        } catch (Exception e) {
        }
    }
}

# Typesense Java Client ☕ 🔍

Java client library for accessing the HTTP API of [Typesense](https://typesense.org) search engine.

## Installation

The client is available on Maven central:

```groovy
dependencies {
    implementation 'org.typesense:typesense-java:1.3.0'
}
```

```xml
<dependency>
    <groupId>org.typesense</groupId>
    <artifactId>typesense-java</artifactId>
    <version>1.3.0</version>
</dependency>
```

```java
import org.typesense.api.*;
import org.typesense.model.*;
import org.typesense.resources.*;
```

## Compatibility
`typesense-java` is compatible with Java versions 8+ and Android SDK versions 26+

## Usage

### Create a new client
```java
List<Node> nodes = new ArrayList<>();
nodes.add(
  new Node(
    "http",       // For Typesense Cloud use https
    "localhost",  // For Typesense Cloud use xxx.a1.typesense.net
    "8108"        // For Typesense Cloud use 443
  )
);

Configuration configuration = new Configuration(nodes, Duration.ofSeconds(2),"<API_KEY>");

Client client = new Client(configuration);
 ```

### Create a new collection
```java
List<Field> fields = new ArrayList<>();
fields.add(new Field().name("countryName").type(FieldTypes.STRING));
fields.add(new Field().name("capital").type(FieldTypes.STRING));
fields.add(new Field().name("gdp").type(FieldTypes.INT32).facet(true).sort(true));

CollectionSchema collectionSchema = new CollectionSchema();
collectionSchema.name("Countries").fields(fields).defaultSortingField("gdp");

client.collections().create(collectionSchema);
```

### Create a new collection from JSON file
```java
String schemaJson = new String(
    Files.readAllBytes(Paths.get("schema.json")),
    StandardCharsets.UTF_8
);
client.collections().create(schemaJson);
```

### Index a document
```java
Map<String, Object> hmap = new HashMap<>();
hmap.put("countryName","India");
hmap.put("capital","Delhi");
hmap.put("gdp", 10);

client.collections("Countries").documents().create(hmap);
```

### Upserting a document
```java
Map<String, Object> hmap = new HashMap<>();
hmap.put("countryName","India");
hmap.put("capital","Delhi");
hmap.put("gdp", 5);

client.collections("Countries").documents().upsert(hmap);
```

### Import batch of documents
```java
ImportDocumentsParameters queryParameters = new ImportDocumentsParameters();
queryParameters.action("create");

String documentList = "{\"countryName\": \"India\", \"capital\": \"Washington\", \"gdp\": 5215}\n" +
                      "{\"countryName\": \"Iran\", \"capital\": \"London\", \"gdp\": 5215}";
// Import your document as JSONL string from a file.
client.collections("Countries").documents().import_(documentList, queryParameters)
```

### Search in a collection
```java
SearchParameters searchParameters = new SearchParameters()
                                        .q("tokoyo")
                                        .queryBy("countryName,capital")
                                        .prefix("true,false");
SearchResult searchResult = client.collections("Countries").documents().search(searchParameters);
```

### Update a document
```java
Map<String, Object> hmap = new HashMap<>();
hmap.put("gdp", 8);
client.collections("Countries").documents("28").update(hmap);
```

### Retrieve a document
```java
client.collections("Countries").documents("28").retrieve();
```

### Delete a document
```java
client.collections("Countries").documents("28").delete();
```

### Delete documents using query
```java
DeleteDocumentsParameters deleteDocumentsParameters = new DeleteDocumentsParameters();
deleteDocumentsParameters.filterBy("gdp:=[2,8]");
deleteDocumentsParameters.batchSize(10);
```

### Retrieve a collection
```java
client.collections("Countries").retrieve();
```

### Retrieve all collections
```java
client.collections().retrieve();
```

### Drop a collection
```java
client.collections("Countries").delete();   
```

### Export a collection
```java
client.collections("Countries").documents().export();
```

### Create an analytics rule
```java
AnalyticsRuleSchema analyticsRule = new AnalyticsRuleSchema();
analyticsRule.setName("popular-queries");
analyticsRule.setType(AnalyticsRuleSchema.TypeEnum.POPULAR_QUERIES);
analyticsRule.setParams(new AnalyticsRuleParameters()
        .source(new AnalyticsRuleParametersSource()
                .collections(Arrays.asList("Countries")))
        .destination(new AnalyticsRuleParametersDestination()
                .collection("top_searches")));

client.analytics().rules().create(analyticsRule);
```

### Upsert an analytics rule
```java
AnalyticsRuleUpsertSchema analyticsRule = new AnalyticsRuleUpsertSchema()
        .type(AnalyticsRuleUpsertSchema.TypeEnum.NOHITS_QUERIES)
        .params(new AnalyticsRuleParameters()
                .source(new AnalyticsRuleParametersSource()
                        .collections(Arrays.asList("Countries")))
                .destination(new AnalyticsRuleParametersDestination()
                        .collection("failed_searches")));

client.analytics().rules().upsert("failed-searches", analyticsRule);
```

### Retrieve all analytics rules
```java
AnalyticsRulesRetrieveSchema rules = client.analytics().rules().retrieve();
```

### Retrieve a single analytics rule
```java
AnalyticsRuleSchema rule = client.analytics().rules("failed-searches").retrieve();
```

### Delete an analytics rule
```java
client.analytics().rules("failed-searches").delete();
```

#### Create an analytics event
```java
AnalyticsEventCreateSchema analyticsEvent = new AnalyticsEventCreateSchema()
        .type("conversion")
        .name("purchase_made")
        .data(Map.of(
                "product_id", "123",
                "user_id", "user_456",
                "amount", "99.99"
        ));

client.analytics().events().create(analyticsEvent);
```

### Upsert a stopwords set
```java
List<String> stopwords = new ArrayList<>();
stopwords.add("the");
stopwords.add("of");
stopwords.add("and");

StopwordsSetUpsertSchema stopwordsSet = new StopwordsSetUpsertSchema();
stopwordsSet.stopwords(stopwords);

client.stopwords().upsert("common-words", stopwordsSet);
```

### Retrieve a stopwords set
```java
